mapper.select:
SELECT employee_id, employee_name, department, usage_count, travel_distance, carbon_amount AS carbon_reduction, CASE WHEN usage_rank <= CEIL(total_employee_count * (#{rewardTargetPercent} / 100.0)) AND usage_count >= #{minimumMonthlyUsageCount} THEN 1 ELSE 0 END AS reward_target FROM ranked_employee_usage
WHERE usage_rank <= CEIL(total_employee_count * (#{rewardTargetPercent} / 100.0)) AND usage_count >= #{minimumMonthlyUsageCount}
ORDER BY usage_count DESC, carbon_amount DESC, employee_id ASC


SELECT
    usage_date,
    usage_count,
    travel_distance,
    carbon_amount
FROM t_employee_usage_stat
WHERE organization_id = #{organizationId}
  AND employee_id = #{employeeId}
  AND usage_date BETWEEN #{startDate} AND #{endDate}
ORDER BY usage_date ASC
